        try{const rows=await files.documentRows(uid);if(activeUserId!==uid||petId!==getActivePetKey())return;for(const row of rows.filter(r=>r.pet_id===petId&&!r.pending))$('vetDocumentChoices').append(choice(row,'vetDocument',`${row.document_date} · ${row.title}`))}catch{if(activeUserId===uid)message('vetSharePage','Для списка документов восстановите связь.',true)}
        if(!$('vetRecordChoices').children.length)$('vetRecordChoices').append(E('p','Записей о здоровье пока нет.'));
