    files.register?.('shared-profile',async(job,client)=>{
        for(let attempt=0;attempt<4;attempt++){
            const result=await client.rpc('petcare_care_profile',{p_owner:job.owner,p_pet:job.petId});if(result.error)throw new Error(result.error.code==='42501'?'care_access_denied':'care_request_failed');
            const conflicts=[];const data=sync.merge(job.base,job.data,result.data.data,'care',conflicts);if(conflicts.length)throw new Error('care_conflict');
            const saved=await client.rpc('petcare_care_profile',{p_owner:job.owner,p_pet:job.petId,p_revision:result.data.revision,p_data:data});if(saved.error)throw saved.error;if(saved.data.conflict)continue;
            if(activeUserId!==job.userId)return;
            const key=`shared:${job.userId}:${job.owner}:${job.petId}`,latest=await sync.get('outbox',job.key),copy=value=>JSON.parse(JSON.stringify(value));
            if(latest&&latest.version!==job.version){const overlaps=[];const rebased=sync.merge(job.data,latest.data,saved.data.data,'care',overlaps);await sync.put('outbox',job.key,{...latest,data:rebased,base:copy(saved.data.data),revision:saved.data.revision,errorCode:overlaps.length?'care_conflict':null});await sync.put('preferences',key,{key,userId:job.userId,owner:job.owner,petId:job.petId,data:rebased,base:copy(saved.data.data),revision:saved.data.revision,pending:true,version:latest.version,conflicts:overlaps});}
            else await sync.put('preferences',key,{key,userId:job.userId,owner:job.owner,petId:job.petId,data:copy(saved.data.data),base:copy(saved.data.data),revision:saved.data.revision,pending:false,version:job.version});return;
        }throw new Error('care_conflict');
    });
    // ZIP STORE with UTF-8 names. Blob parts keep originals out of JS heap while
